/// <summary>
/// Document Handler class for cancelling pick lines.
/// </summary>
[
    TFMTableName(tableStr(InventJournalTable)),    
    TFMDocumentType(classStr(TFMPostAdhocRegistration), staticMethodStr(MobConstants,CancelPickLine),methodStr(MobDocCancelPickLine,postCancelPickLine)),
    TFMMenu(staticMethodStr(MobConstants,CancelPickLine),"@MobileWMS:CancelPickLine","@MobileWMS:CancelPickLine", methodStr(MobimageHandlerCombinedImages,cancelPickLine),false,true)
]
class MobDocCancelPickLine extends TFMDocumentHandler
{
    WMSOrderTrans           wmsOrderTrans;
}

Method.Source:
/// <summary>
///
/// </summary>
/// <returns></returns>
public TFMDocumentHandlerDescription description()
{
    TFMDocumentHandlerDescription ret;
    ret = "@MobileWMS:CancelPickLine";
    return ret;
}

    /// <summary>
    /// Method used to declare or modify pages pertaining to this class.
    /// </summary>
    /// <returns>A TFMPages Object containing all pages declared or autogenerated in the class.</returns>
    public TFMPages pages()
    {
        TFMPages ret;
        TFMPageUnplannedItemRegistration page;
        TFMPageUnplannedItemRegistrationConfiguration config;
		ret = super();
        page = ret.getPage(MobConstants::CancelPickLine());
        config = page.getConfiguration();
        config.parmAutomaticAcceptOnOpen(false);
        return ret;
    }

/// <summary>
/// Cancels a pick list line and if cancelDeliveryRemainder is #true, also cancels amount (_remainingQty) on pick order. splits line if quantity is less than total quantity
/// </summary>
[TFMPostMethod(tableStr(WMSOrderTrans))]
public void postCancelPickLine()
{
    str                     returnstr              = "@SYS40221";  //returnstatement to mobile device
    TFMRequestItemAndDimensionElement  docRequest  = request;
    RecId                   recId                  = str2int64(docRequest.parmLineNumber()); //Pickline recid
    str                     recIdString            = docRequest.parmLineNumber();
    InventQty               cancelInventQty        = docRequest.parmQuantity();     //Qty to cancel
    InventQty               remainingInventQtyToCancel = 0;
    MobPageDatasources      mobPageDatasources;
    WMSOrderTrans           wmsOrderTransGrouped;
    boolean                 updateSalesSuccess = true;

    wmsOrderTrans.selectForUpdate(true);

    select firstOnly * from wmsOrderTrans
        where wmsOrderTrans.RecId == recID;

    if(wmsOrderTrans) // buffer found, procees orderline as usual
    {
        updateSalesSuccess = this.cancelPickLine(wmsOrderTrans, cancelInventQty);

        if(updateSalesSuccess)  //if no error was detected
        {
            returnstr = "@SYS16147";
        }
        else                    //if salesorderline was not updated
        {
            throw error("@SYS78886");
        }
    }
    else
    {
        // If line is grouped throw an error
        if(subStr(recIdString, 1, 2) == MobConstants::GroupedLinesPrefix())
        {
            throw error("@MobileWMS:Thepickinglineisgroupedonthedata");
        }

        // Throw error if a quantity for cancelation remains
        if(remainingInventQtyToCancel)
        {
            throw Error(strFmt("@MobileWMS:Theproposedquantityforcancellati", cancelInventQty, remainingInventQtyToCancel));
        }
    }

    resultStr = returnstr;

}

protected boolean cancelPickLine(WMSOrderTrans _wmsOrderTrans, InventQty _cancelInventQty)
{
    boolean                 updateSalesSuccess = true;
    InventQty               remainingInventQty;
    WMSOrderTrans           wmsOrderTransCancel;
    WMSPickingLineCancel    wmsPickingLineCancel;
    InventTransferLine      inventTransferLine;
    NoYes                   removeCancelLinesFromOrder = MobParameters::find().CancelQtyOnOrder;

    if (_wmsOrderTrans.inventTransType == InventTransType::TransferOrderShip || _wmsOrderTrans.inventTransType == InventTransType::Sales)
    {
        remainingInventQty = (_wmsOrderTrans.qty-_cancelInventQty);


        if (remainingInventQty < 0)              //is the cancled qty is larger than the total remaining qty
        {
            throw error("@SYS1036"+': '+ MobHelper::formatItemQty(_wmsOrderTrans.qty, _wmsOrderTrans.unitId()));
        }
        if (_cancelInventQty <= 0)                //is the cancled qty less than or equal to 0
        {
            throw error("@SYS113821");
        }

        if(remainingInventQty > 0 && _cancelInventQty > 0)    //check if the order must be split up, if not the whole order is cancled
        {
            wmsOrderTransCancel = _wmsOrderTrans.split(_cancelInventQty, _wmsOrderTrans.PdsCWQty);
            wmsPickingLineCancel = WMSPickingLineCancel::newWMSPickingLineCancel(wmsOrderTransCancel);
            #ifnot.isAX6
            wmsPickingLineCancel.runOperation();
            #endif
            #if.isAX6
            wmsPickingLineCancel.run();
            #endif
        }
        else
        {
            wmsPickingLineCancel = WMSPickingLineCancel::newWMSPickingLineCancel(_wmsOrderTrans);
            #ifnot.isAX6
            wmsPickingLineCancel.runOperation();
            #endif
            #if.isAX6
            wmsPickingLineCancel.run();
            #endif
        }


        if(RemoveCancelLinesFromOrder && _wmsOrderTrans.inventTransType == InventTransType::TransferOrderShip)       //Update deliveryRemainder for Transfer orders
        {
            inventTransferLine = InventTrans::findTransId(_wmsOrderTrans.inventTransId).inventTransferLine(true);
            inventTransferLine.QtyRemainShip = inventTransferLine.QtyTransfer - (inventTransferLine.QtyShipped + _cancelInventQty);
            inventTransferLine.updateDeliverRemainder();
            inventTransferLine.update();
        }
        else if(RemoveCancelLinesFromOrder && _wmsOrderTrans.inventTransType == InventTransType::Sales)             //Update deliveryRemainder for sales orders
        {
            #ifnot.isAX6
            updateSalesSuccess = SalesUpdateRemain::construct().updateDeliverRemainder(SalesLine::findInventTransId(_wmsOrderTrans.inventTransId, true), remainingInventQty, remainingInventQty);
            #endif
            #if.isAX6
            updateSalesSuccess = SalesUpdateRemain::updateDeliveryRemainder(SalesLine::findInventTransId(_wmsOrderTrans.inventTransId, true), remainingInventQty, remainingInventQty);
            #endif
        }
    }
    else
    {
        return false;
    }

    return updateSalesSuccess;
}

/// <summary>
/// Header elements for the cancel picking line page
/// </summary>
/// <returns>An XML string with the header/filter definitions.</returns>
[TFMReferenceDataMethod]
public TFMReferenceDataConfiguration CancelPickLineHeader()
{
    TFMReferenceDataConfiguration refConf = new TFMReferenceDataConfiguration();
    refConf.addCollector(TFMGetReferenceData::defaultItemIdCollector(1,false,true));        
    refConf.addCollector(TFMGetReferenceData::defaultLineNumberCollector(2, true));
    refConf.addCollector(TFMGetReferenceData::defaultQuantityElement(3));
    return refConf;
}
